  "var_renames": {
    "v4": "current_end",
    "v5": "buffer_end",
    "v6": "element_id",
    "v7": "element_total_len",
    "v8": "element_start"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "802.11 element ID; 0xFF denotes an extended element ID field"
    },
    {
      "offset": 1,
      "meaning": "element length byte; full element length is this value plus the 2-byte header"
    },
    {
      "offset": 2,
      "meaning": "extended element ID compared against the requested target"
    }
  ]
}
